{
  "vars": [
    {
      "name": "first_guess",
      "type": "Nat",
      "unit": "jelly beans",
      "def": "80"
    },
    {
      "name": "second_guess",
      "type": "Int",
      "unit": "jelly beans",
      "def": "20 + first_guess / 2",
      "nonzero": "2 != 0"
    },
    {
      "name": "third_guess",
      "type": "Int",
      "unit": "jelly beans",
      "def": "first_guess + first_guess / 4",
      "nonzero": "4 != 0"
    },
    {
      "name": "average_guess",
      "type": "Int",
      "unit": "jelly beans",
      "def": "(first_guess + second_guess + third_guess) / 3",
      "nonzero": "3 != 0"
    }
  ],
  "claims": [
    "first_guess is the first friend's guess of 80 jelly beans.",
    "second_guess is 20 more than half the first friend's guess.",
    "third_guess is 25% more than the first friend's guess.",
    "average_guess is the arithmetic mean of the three guesses."
  ],
  "goal": "average_guess",
  "answer": 80
}

{
  "vars": [
    {
      "name": "full_service_years",
      "type": "Nat",
      "unit": "year",
      "def": "40"
    },
    {
      "name": "full_annual_pension",
      "type": "Int",
      "unit": "USD/year",
      "def": "50000"
    },
    {
      "name": "vesting_start_years",
      "type": "Nat",
      "unit": "year",
      "def": "20"
    },
    {
      "name": "years_worked",
      "type": "Nat",
      "unit": "year",
      "def": "30"
    },
    {
      "name": "accrual_rate_per_year",
      "type": "Rat",
      "unit": "1/year",
      "def": "0.05"
    },
    {
      "name": "additional_years",
      "type": "Nat",
      "unit": "year",
      "def": "years_worked - vesting_start_years"
    },
    {
      "name": "pension_fraction",
      "type": "Rat",
      "unit": null,
      "def": "additional_years * accrual_rate_per_year"
    },
    {
      "name": "annual_pension",
      "type": "Rat",
      "unit": "USD/year",
      "def": "full_annual_pension * pension_fraction"
    }
  ],
  "claims": [
    "full_service_years is the number of years required for the full pension",
    "full_annual_pension is the annual pension after full_service_years",
    "vesting_start_years is the number of years after which pension starts accruing",
    "years_worked is the number of years Marcy worked",
    "accrual_rate_per_year is the fraction of the full pension earned for each additional year after vesting_start_years",
    "additional_years is how many years beyond vesting_start_years Marcy worked",
    "pension_fraction is the total fraction of the full annual pension Marcy has earned",
    "annual_pension is Marcy's annual pension after quitting"
  ],
  "goal": "annual_pension",
  "answer": 25000
}

{
  "vars": [
