    },
    {
      "name": "doll_cost",
      "type": "Nat",
      "unit": "dollars",
      "def": "3 * action_figure_cost"
    },
    {
      "name": "total_red_cars_cost",
      "type": "Nat",
      "unit": "dollars",
      "def": "num_red_cars * red_car_cost"
    },
    {
      "name": "total_action_figures_cost",
      "type": "Nat",
