  ],
  "claims": [
    "action_figure_cost is the cost of one action figure in dollars",
    "red_car_cost is the cost of one red car in dollars",
    "num_red_cars is the number of red cars among the toys",
    "num_action_figures is the number of action figures among the toys",
    "num_dolls is the number of dolls among the toys",
    "doll_cost is the cost of the doll, equal to the cost of 3 action figures",
    "total_red_cars_cost is the combined cost of all red cars",
    "total_action_figures_cost is the combined cost of all action figures",
    "total_dolls_cost is the combined cost of all dolls",
    "total_toys_cost is the total worth of all toys"
  ],
  "goal": "total_toys_cost",
  "answer": 50
}

{
  "vars": [
    {
      "name": "current_age_sum",
      "type": "Nat",
      "unit": "years",
      "def": "28 - 4"
    },
    {
      "name": "brooke_age",
      "type": "Nat",
      "unit": "years",
      "def": "current_age_sum / 3",
      "nonzero": "3 != 0"
    },
    {
      "name": "seth_age",
      "type": "Nat",
      "unit": "years",
      "def": "2 * brooke_age"
    }
  ],
  "claims": [
    "current_age_sum is the sum of Seth's and Brooke's current ages; since in 2 years each gains 2 years and the total is 28, the current sum is 28 - 4.",
    "brooke_age is Brooke's current age, obtained from the current sum divided by 3 because Seth is twice Brooke's age.",
    "seth_age is Seth's current age, twice Brooke's age."
  ],
  "goal": "seth_age",
  "answer": 16
}
